    // Définir le mot à rechercher
    string mot_a_rechercher = "mot_a_rechercher";

    // Ouvrir le fichier
    string fichier = "fichier.txt";
    ifstream myFile(fichier);

    // Vérifier si le fichier a été ouvert avec succès
